SET wallet.fail_send='yes';
UPDATE public.agents SET agent_wallet_balance=12 WHERE id=1;
DO $$ BEGIN
 IF (SELECT agent_wallet_balance FROM public.agents WHERE id=1)<>12 OR (SELECT count(*) FROM public.deliveries)<>6 THEN RAISE EXCEPTION 'transport outage rolled back wallet or invented signal'; END IF;
 IF has_function_privilege('authenticated','public.fn_publish_agent_wallet_change()','EXECUTE') OR has_function_privilege('anon','public.fn_publish_agent_wallet_change()','EXECUTE') OR has_function_privilege('service_role','public.fn_publish_agent_wallet_change()','EXECUTE') THEN RAISE EXCEPTION 'trigger exposed'; END IF;
END $$;
